CREATE TABLE task_schedule(task_id TEXT PRIMARY KEY REFERENCES tasks(id),revision INTEGER NOT NULL,document TEXT NOT NULL);
CREATE TABLE recurrence_series(id TEXT PRIMARY KEY,actor TEXT NOT NULL REFERENCES users(id),spec TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('active','paused','stopped')),revision INTEGER NOT NULL DEFAULT 1,emitted INTEGER NOT NULL DEFAULT 1);
CREATE TABLE recurrence_occurrences(series_id TEXT NOT NULL REFERENCES recurrence_series(id),ordinal INTEGER NOT NULL,task_id TEXT UNIQUE NOT NULL REFERENCES tasks(id),due_local TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed','skipped','reopened')),PRIMARY KEY(series_id,ordinal));
CREATE UNIQUE INDEX recurrence_one_outstanding ON recurrence_occurrences(series_id) WHERE status='pending';
CREATE TABLE reminder_outbox(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),schedule_revision INTEGER NOT NULL,recipient TEXT NOT NULL REFERENCES users(id),channel TEXT NOT NULL CHECK(channel IN ('email','push')),at INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','leased','delivered','cancelled','dead')),attempts INTEGER NOT NULL DEFAULT 0,available_at INTEGER NOT NULL,lease_owner TEXT,lease_token TEXT,lease_until INTEGER,last_error TEXT,UNIQUE(task_id,schedule_revision,channel,at));
CREATE INDEX reminder_ready ON reminder_outbox(status,available_at,lease_until);
